// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess, uint256 lockBlock) public {
        lockBlock = bound(lockBlock, 1, 1000);
        vm.roll(lockBlock);

        vm.deal(address(this), 2 ether);
        c.lockInGuess{value: 1 ether}(guess);

        // Mine the answer: guess is correct if it equals keccak(blockhash(lockBlock + 1))
        vm.roll(lockBlock + 2);

        vm.deal(address(this), 0);

        // Try to settle. If it succeeds, the reference clears state AFTER transfer,
        // so a re-entrant call can't pay again; the bug clears state BEFORE transfer,
        // so re-entrancy succeeds and drains the contract without a second valid guess.
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // Force re-entrancy attempt from this caller, which is now the guesser.
        bool reentrantOk;
        try c.settle() { reentrantOk = true; } catch { reentrantOk = false; }

        // General rule: after any sequence of settle calls by the guesser, the contract
        // balance must be at least 2 ether if no valid payout was made, or the contract
        // must not be drained by a second settle that produces no additional correct guess.
        // In reference C, a successful settle pays exactly 2 ether and clears the lock
        // before the transfer is attempted, so any re-entrant settle sees block==0 and reverts.
        // In buggy M, the first settle can succeed and clear the lock before the transfer,
        // enabling a re-entrant settle that also succeeds (ok && reentrantOk).
        assertTrue(!(ok && reentrantOk), "reentrant settle must not succeed");
    }
}
